    if (EVENT_STATUS[event.status] !== undefined) lastEvent.set(node, event)
    const attempt = attemptFromMessage(event.message)
    if (attempt !== null) eventAttempt.set(node, Math.max(attempt, eventAttempt.get(node) ?? 0))
  }
